    march: ["مارچ", "مارچ کے لیے اصل شہر اور منتخب لوگ چاہیے۔ ٹائل چھونا صرف ہدف ہے۔ سمندری سفر بندرگاہ اور نقل؛ سمندری جنگ میں ترائیریم اور کپتان بھی۔ ٹوہ/مدد کے لیے صرف بندرگاہ اور نقل۔"],
    reports: ["رپورٹیں", "مارچ پہنچنے پر خط آپ کے ان باکس میں آتا ہے۔ اوپر رپورٹیں کھولیں—فتح یا مشن سے تلاش کے ساتھ بڑی تختی۔"],
    market: ["بازار", "شخص کارڈ فہرست مفت۔ فروخت پر خریدار دیتا ہے: 90٪ بیچنے والے کو، 10٪ فیس۔ خریدنے کے لیے اپنا شہر چاہیے۔"],
    guild: ["گلڈ", "گلڈ دعوے بانٹتی ہے۔ نکلنے کے بعد ایک مہینہ دوسری گلڈ نہیں۔ شہر اور گلڈ کے نام آپ کے لکھے رہتے ہیں۔"],
    atlas: ["اطلس", "دنیا کا اوپر سے منظر۔ نقشہ، 0,0 جیسے نقاط یا اپنا شہر تلاش کر کے 3D نقشے میں داخل ہوں۔"],
    roster: ["فہرست", "فہرست آپ کے شہر، لوگ، غلام، رسد اور راستے کے مارچ دکھاتی ہے۔ چھلانگ کے لیے ایک چیز چھویں؛ نام نقشے پر نہیں بچھتے۔"],
    towns: ["نظامی بستیاں", "ہر 100، 1000، 10000 ٹائل پر نظامی قصبہ/شہر/میٹروپولس ہے۔ قبضہ، لوٹ، قتل عام جائز۔ تباہی ممنوع ہے۔"],
