    guild: ["กิลด์", "กิลด์ใช้ช่องที่ยึดร่วมกัน ออกแล้วห้ามเข้ากิลด์อื่นหนึ่งเดือน ชื่อเมืองและกิลด์คงข้อความที่คุณพิมพ์"],
    atlas: ["แผนที่ใหญ่", "มองโลกจากด้านบน ค้นชื่อแผนที่ พิกัดเช่น 0,0 หรือเมืองของคุณ แล้วเข้าแผนที่สามมิติ"],
    roster: ["บัญชีรายชื่อ", "บัญชีแสดงเมือง คน ทาส เสบียง และการเดินทัพระหว่างทาง แตะรายการเพื่อกระโดด ชื่อไม่ถูกโปรยบนแผนที่"],
    towns: ["เมืองระบบ", "ทุก 100, 1000 และ 10000 ช่องมีเมืองเล็ก เมือง หรือมหานครของระบบ ยึด ปล้น หรือสังหารได้ ห้ามทำลาย"],
